import {reserveCaption} from './family-layout.js?v=20261023-physicscomplete01';
import {bounds,fitDistance,zoomLimits,particleColours} from './model-geometry.js?v=20261023-physicscomplete01';
import {moleculeDiagram} from './model-diagrams.js?v=20261023-physicscomplete01';
import * as THREE from './assets/three.module.js';
const $=s=>document.querySelector(s);
const sceneEl=$('#scene');let renderer,scene,camera,group,decorativeRing;let angle=.25,tilt=.12,zoom=7.5,drag=false,lastX=0,lastY=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,diagram=false;
const atomColor=particleColours,radius={Ca:.5,K:.13,Focus:.2,X:.24,H:.48,O:.75,C:.68,P:.17,N:.17,E:.09,Fe:.48,Cu:.48,Iplus:.36,Iminus:.43};
export const models={oxygen:{name:'Oxygen',formula:'O₂',kicker:'ONE TYPE OF ATOM',atoms:[['O',-.75,0,0],['O',.75,0,0]],bonds:[[0,1]]},water:{name:'Water',formula:'H₂O',kicker:'TWO TYPES OF ATOM',atoms:[['O',0,.25,0],['H',-1,-.45,0],['H',1,-.45,0]],bonds:[[0,1],[0,2]]},carbon:{name:'Carbon dioxide',formula:'CO₂',kicker:'TWO TYPES OF ATOM',atoms:[['C',0,0,0],['O',-1.35,0,0],['O',1.35,0,0]],bonds:[[0,1],[0,2]]},hydrogen:{name:'Hydrogen',formula:'H₂',kicker:'ONE TYPE OF ATOM',atoms:[['H',-.5,0,0],['H',.5,0,0]],bonds:[[0,1]]},mixture:{name:'A mixture',formula:'H₂ + O₂',kicker:'SUBSTANCES PHYSICALLY MIXED',atoms:[['O',-.8,.7,0],['O',.7,.7,0],['H',-.5,-1,.3],['H',.5,-1,.3]],bonds:[[0,1],[2,3]]}};
models.methane={zoom:10.5,name:'Methane',formula:'CH₄',kicker:'TETRAHEDRAL MOLECULE · SYMBOLIC SIZES',atoms:[['C',0,0,0],['H',.85,.85,.85],['H',.85,-.85,-.85],['H',-.85,.85,-.85],['H',-.85,-.85,.85]],bonds:[[0,1],[0,2],[0,3],[0,4]]};
let model=models.oxygen,modelRadius=1,baseZoom=7.5,zoomRatio=1;
function fitView(){if(!camera)return;baseZoom=fitDistance(modelRadius,camera.aspect);zoom=baseZoom*zoomRatio;}
function changeZoom(factor){const limits=zoomLimits(baseZoom);zoom=Math.min(limits.max,Math.max(limits.min,zoom*factor));zoomRatio=zoom/baseZoom;}
function resetView(){angle=.25;tilt=.12;zoomRatio=1;fitView();}
try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x000000,0);renderer.localClippingEnabled=true;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;sceneEl.append(renderer.domElement);scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(36,1,.1,100);scene.add(new THREE.AmbientLight(0xe4e8eb,1.3));const key=new THREE.DirectionalLight(0xf8f6f2,5);key.position.set(-3,5,4);scene.add(key);const rim=new THREE.DirectionalLight(0xb7c8d6,3);rim.position.set(4,1,-3);scene.add(rim);const fill=new THREE.DirectionalLight(0xd4dfe7,1);fill.position.set(0,-3,2);scene.add(fill);const ring=new THREE.Mesh(new THREE.TorusGeometry(2.5,.008,8,100),new THREE.MeshBasicMaterial({color:0xb7c8d6,transparent:true,opacity:.17}));ring.rotation.x=1.1;ring.rotation.z=-.35;scene.add(ring);decorativeRing=ring;group=new THREE.Group();scene.add(group);new ResizeObserver(resize).observe(sceneEl);resize();}catch{diagram=true;$('#scene').hidden=true;$('#diagram').hidden=false;$('#viewToggle').textContent='2D fallback';$('#viewToggle').disabled=true;$('.live-pill').textContent='Diagram';}
function resize(){if(!renderer)return;const w=sceneEl.clientWidth,h=sceneEl.clientHeight;if(!w||!h)return;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();fitView();}
export function renderModel(m){const same=!!m.viewKey&&m.viewKey===model.viewKey;model=m;if(m.startPaused&&!same){paused=true;$('#rotateToggle').setAttribute('aria-pressed','true');$('#rotateToggle').textContent='Rotate model ▷';}if(decorativeRing)decorativeRing.visible=!/SHELL|HISTORICAL|IONIC|SCHEMATIC|CUTAWAY/.test(m.kicker);$('#sceneName').textContent=m.name;$('#sceneKicker').textContent=m.kicker;$('#sceneFormula').textContent=m.formula;sceneEl.setAttribute('aria-label',m.aria||`${m.name}: ${m.atoms.map(a=>a[0]).join(', ')}. Drag or use arrow keys to rotate. Plus and minus zoom.`);$('#diagram').innerHTML=m.diagram||moleculeDiagram(m);let cellNote=$('#cellScaleNote');if(m.note){if(!cellNote){cellNote=document.createElement('small');cellNote.id='cellScaleNote';cellNote.className='cell-scale-note';$('.scene-title').append(cellNote);}cellNote.textContent=m.note;}else cellNote?.remove();reserveCaption();const extent=bounds(m.atoms,m.cubeSize?m.cubeSize*Math.sqrt(3)/2:(m.atomSize??Math.max(.2,...m.atoms.map(([el])=>radius[el]??.4))));modelRadius=m.radius??extent.radius;if(!same)resetView();else fitView();if(!group)return;while(group.children.length){const o=group.children[0];o.traverse(child=>{child.geometry?.dispose();if(child.material)for(const mat of (Array.isArray(child.material)?child.material:[child.material])){mat.map?.dispose();mat.dispose();}});group.remove(o);}m.atoms.forEach(([el,x,y,z])=>{const sphere=new THREE.Mesh(m.cubeSize?new THREE.BoxGeometry(m.cubeSize,m.cubeSize,m.cubeSize):new THREE.SphereGeometry(m.atomSize??radius[el]??.4,48,32),new THREE.MeshStandardMaterial({color:atomColor[el]??particleColours[el]??0xb7c8d6,metalness:.16,roughness:.28}));sphere.position.set(x-extent.centre[0],y-extent.centre[1],z-extent.centre[2]);group.add(sphere);});m.bonds.forEach(([i,j])=>{const a=new THREE.Vector3(...m.atoms[i].slice(1)),b=new THREE.Vector3(...m.atoms[j].slice(1)),dir=b.clone().sub(a);const bond=new THREE.Mesh(new THREE.CylinderGeometry(m.bondRadius??.105,m.bondRadius??.105,dir.length(),20),new THREE.MeshStandardMaterial({color:0xd4dfe7,metalness:.3,roughness:.35}));bond.position.copy(a.clone().add(b).multiplyScalar(.5));bond.position.sub(new THREE.Vector3(...extent.centre));bond.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),dir.normalize());group.add(bond);});if(m.build)m.build(group,THREE);}
let previous=0;function animate(t){requestAnimationFrame(animate);if(!renderer||diagram)return;if(!paused&&!drag)angle+=Math.min((t-previous)/1000,.04)*.12;previous=t;group.rotation.y=angle;group.rotation.x=tilt;camera.position.set(0,.1,zoom);camera.lookAt(0,0,0);renderer.render(scene,camera);}requestAnimationFrame(animate);
sceneEl.addEventListener('pointerdown',e=>{drag=true;lastX=e.clientX;lastY=e.clientY;sceneEl.setPointerCapture(e.pointerId);});sceneEl.addEventListener('pointermove',e=>{if(drag){angle+=(e.clientX-lastX)*.009;tilt+=(e.clientY-lastY)*.007;lastX=e.clientX;lastY=e.clientY;}});sceneEl.addEventListener('pointerup',()=>drag=false);sceneEl.addEventListener('pointercancel',()=>drag=false);sceneEl.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','Home','0'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')angle-=.15;if(e.key==='ArrowRight')angle+=.15;if(e.key==='ArrowUp')tilt-=.15;if(e.key==='ArrowDown')tilt+=.15;if(e.key==='+'||e.key==='=')changeZoom(.9);if(e.key==='-')changeZoom(1.1);if(e.key==='Home'||e.key==='0')resetView();}});$('#rotateToggle').setAttribute('aria-pressed',String(paused));$('#zoomIn').onclick=()=>changeZoom(.9);$('#zoomOut').onclick=()=>changeZoom(1.1);$('#resetView').onclick=resetView;
$('#rotateToggle').onclick=()=>{paused=!paused;$('#rotateToggle').setAttribute('aria-pressed',String(paused));$('#rotateToggle').textContent=paused?'Rotate model ▷':'Stop rotation Ⅱ';};$('#rotateToggle').textContent=paused?'Rotate model ▷':'Stop rotation Ⅱ';$('#viewToggle').onclick=()=>{diagram=!diagram;$('#scene').hidden=diagram;$('#diagram').hidden=!diagram;$('#viewToggle').textContent=diagram?'3D model ↗':'2D diagram ↗';$('.live-pill').textContent=diagram?'Diagram':'3D model';$('#modelViewControls').hidden=diagram;$('#rotateToggle').hidden=diagram;$('.scene-bottom>span').hidden=diagram;if(!diagram)resize();};

export function renderAtom(el, neutrons=el.mass-el.z, charge=0){
 const count=Math.max(0,el.z-charge),atoms=[],bonds=[];
 for(let i=0;i<el.z+neutrons;i++){const a=i*2.39996,r=.10*Math.cbrt(i+1);atoms.push([i<el.z?'P':'N',Math.cos(a)*r,Math.sin(a)*r,(i%3-1)*.14]);}
 const shells=[];let left=count;for(const cap of [2,8,8,2]){const n=Math.min(left,cap);if(n>0)shells.push(n);left-=n;}
 shells.forEach((n,k)=>{const r=.9+k*.58;for(let i=0;i<n;i++){const a=2*Math.PI*i/n+.3;atoms.push(['E',r*Math.cos(a),r*Math.sin(a),0]);}});
 const rings=shells.map((n,k)=>{const r=45+k*27;return `<circle cx="150" cy="135" r="${r}" fill="none" stroke="#b7c8d6" stroke-opacity=".5"/>`+Array.from({length:n},(_,i)=>{const a=2*Math.PI*i/n+.3;return `<circle cx="${150+r*Math.cos(a)}" cy="${135+r*Math.sin(a)}" r="4" fill="#d4dfe7"/>`;}).join('');}).join('');
 renderModel({zoom:9.5,name:el.name+'-'+(el.z+neutrons),formula:el.symbol+(charge?charge>0?` ${charge}+`:` ${-charge}−`:''),kicker:'SIMPLIFIED SHELL MODEL · NOT TO SCALE',atoms,bonds,diagram:`<svg viewBox="0 0 300 285" role="img" aria-label="${el.name}: ${el.z} protons, ${neutrons} neutrons, ${count} electrons" class="shell-diagram">${rings}<circle cx="150" cy="135" r="21" fill="#ed8b78"/><text x="150" y="132" text-anchor="middle" fill="#182e44" font-size="10">${el.z} p</text><text x="150" y="145" text-anchor="middle" fill="#182e44" font-size="10">${neutrons} n</text><text x="150" y="277" text-anchor="middle" fill="#d4dfe7" font-size="10">${shells.join(', ')} · ${count} electrons</text></svg>`});
 sceneEl.setAttribute('aria-label',`${el.name}: ${el.z} protons, ${neutrons} neutrons, ${count} electrons. Shells ${shells.join(', ')}. Not to scale.`);
 if(group)shells.forEach((n,k)=>{const ring=new THREE.Mesh(new THREE.TorusGeometry(.9+k*.58,.008,8,80),new THREE.MeshBasicMaterial({color:0xb7c8d6,transparent:true,opacity:.45}));ring.position.sub(new THREE.Vector3(...bounds(atoms).centre));group.add(ring);});
}
export function renderDiagram(title,formula,html,kicker='INTERACTIVE SCIENCE MODEL'){
 diagram=true;$('.live-pill').textContent='Model';renderModel({name:title,formula,kicker,atoms:[],bonds:[],diagram:html});
 $('#diagram').hidden=false;$('#scene').hidden=true;$('#modelViewControls').hidden=true;$('#diagram').querySelectorAll('svg[role=img]').forEach(el=>{if(!el.getAttribute('aria-label'))el.setAttribute('aria-label',title+'. '+formula+'. '+el.textContent.trim());});$('#viewToggle').hidden=true;$('#rotateToggle').hidden=true;$('.scene-bottom>span').hidden=true;
}
export function enable3D(){ $('#modelViewControls').hidden=!renderer; $('#viewToggle').textContent=renderer?'2D diagram ↗':'2D fallback';$('.live-pill').textContent=renderer?'3D model':'Diagram'; $('#viewToggle').hidden=!renderer;$('#rotateToggle').hidden=!renderer;$('.scene-bottom>span').hidden=!renderer;$('#diagram').hidden=!!renderer;$('#scene').hidden=!renderer;diagram=!renderer;if(renderer)resize(); }

export function renderHistory(kind){
 const atoms=kind==='solid'?[['C',0,0,0]]:kind==='plum'?[['P',0,0,0],['E',-.25,.4,.35],['E',.4,-.2,.3],['E',-.3,-.3,-.4]]:[['P',-.12,0,0],['P',.12,0,0],['E',-1.6,0,0],['E',1.6,0,0]];
 renderModel({zoom:8,name:{solid:'The indivisible sphere',plum:'Plum pudding',nuclear:'The nuclear atom'}[kind],formula:kind==='solid'?'Early model':kind==='plum'?'Spread-out positive charge':'Tiny positive nucleus',kicker:'HISTORICAL MODEL · NOT TO SCALE',atoms,bonds:[],diagram:`<svg class="shell-diagram" viewBox="0 0 300 285" role="img" aria-label="${kind} historical model">${kind==='solid'?'<circle cx="150" cy="135" r="80" fill="#71808c"/>':kind==='plum'?'<circle cx="150" cy="135" r="90" fill="#ed8b78" opacity=".55"/><text x="145" y="138" fill="#182e44" font-size="30">+</text><circle cx="110" cy="100" r="9" fill="#d4dfe7"/><circle cx="190" cy="140" r="9" fill="#d4dfe7"/><circle cx="125" cy="180" r="9" fill="#d4dfe7"/>':'<circle cx="150" cy="135" r="90" fill="none" stroke="#71808c"/><circle cx="150" cy="135" r="12" fill="#ed8b78"/><text x="145" y="140" fill="#182e44">+</text><circle cx="60" cy="135" r="6" fill="#d4dfe7"/><circle cx="240" cy="135" r="6" fill="#d4dfe7"/>'}<text x="150" y="270" text-anchor="middle" fill="#d4dfe7" font-size="11">Schematic historical representation · not to scale</text></svg>`});
 if(kind==='plum'&&group){const ball=group.children[0];ball.scale.setScalar(7);ball.material.transparent=true;ball.material.opacity=.3;modelRadius=Math.max(modelRadius,1.5);fitView();}
}
export function renderMetal(symbol){const atoms=[];for(let y=0;y<2;y++)for(let x=0;x<3;x++)for(let z=0;z<2;z++)atoms.push([symbol,(x-1)*.9,(y-.5)*.9,(z-.5)*.9]);renderModel({zoom:8,name:symbol==='Fe'?'Iron':'Copper',formula:symbol,kicker:'SYMBOLIC METAL SAMPLE · ATOMS NOT TO SCALE',atoms,bonds:[]});}

export function renderLattice(mode='3d'){
 const atoms=[];for(let x=0;x<4;x++)for(let y=0;y<4;y++)for(let z=0;z<4;z++)atoms.push([(x+y+z)%2?'Iminus':'Iplus',(x-1.5)*.82,(y-1.5)*.82+.5,(z-1.5)*.82]);
 const slice=Array.from({length:16},(_,i)=>{const x=i%4,y=Math.floor(i/4),plus=(x+y)%2===0;return `<circle cx="${67+x*55}" cy="${42+y*55}" r="22" fill="${plus?particleColours.Iplus:particleColours.Iminus}"/><text x="${67+x*55}" y="${46+y*55}" fill="#182e44" text-anchor="middle" font-size="11">${plus?'Na⁺':'Cl⁻'}</text>`;}).join('');
 renderModel({zoom:11.2,name:'Sodium chloride lattice',formula:'NaCl · 1 : 1',kicker:'GIANT IONIC STRUCTURE · SMALL SAMPLE · NOT TO SCALE',atoms,bonds:[],diagram:`<svg class="shell-diagram" viewBox="0 0 300 285" role="img" aria-label="A 2D slice of alternating positive sodium ions and negative chloride ions">${slice}<text x="150" y="270" fill="#d4dfe7" text-anchor="middle" font-size="10">Flat slice: the real lattice extends in all three directions.</text></svg>`});
 sceneEl.setAttribute('aria-label','Small 3D sodium chloride lattice sample: 32 sodium ions, Na plus, and 32 chloride ions, Cl minus, alternating in a 1 to 1 ratio. A real lattice extends beyond this sample. Drag or use arrow keys to rotate.');
 if(mode==='slice'){diagram=true;$('#scene').hidden=true;$('#diagram').hidden=false;$('#modelViewControls').hidden=true;$('#rotateToggle').hidden=true;$('.scene-bottom>span').hidden=true;$('#viewToggle').textContent='3D model ↗';$('.live-pill').textContent='Diagram';}
}
export function renderBond(kind){
 if(kind==='ionic'){renderLattice();return;}zoom=8;
 if(kind==='covalent')renderModel({zoom:8,name:'A shared electron pair',formula:'H₂ · covalent bond',kicker:'SHARED ELECTRONS ATTRACT BOTH NUCLEI · SCHEMATIC',atoms:[['H',-.8,0,0],['H',.8,0,0],['E',0,.18,.3],['E',0,-.18,.3]],bonds:[[0,1]]});
 else {const atoms=[];for(let x=0;x<3;x++)for(let y=0;y<2;y++)atoms.push(['Fe',(x-1)*.95,(y-.5)*.95,0]);for(let i=0;i<9;i++)atoms.push(['E',Math.cos(i*2.4)*1.4,Math.sin(i*2.4),.5]);renderModel({zoom:8,name:'Metallic bonding',formula:'Positive ions + delocalised electrons',kicker:'SCHEMATIC · ELECTRONS EXTEND THROUGH THE STRUCTURE',atoms,bonds:[]});}
}

export function renderCustomModel(m){const same=m.viewKey===model.viewKey,flat=diagram;renderModel(m);enable3D();if(same&&flat&&renderer){diagram=true;$('#scene').hidden=true;$('#diagram').hidden=false;$('#viewToggle').textContent='3D model ↗';$('.live-pill').textContent='Diagram';$('#modelViewControls').hidden=true;$('#rotateToggle').hidden=true;$('.scene-bottom>span').hidden=true;}}
